import {validateBundle,tracerAnalysis,microAnalysis,measureAnalysis,caseMatches,expertAdvice,compareProduction,TABLES} from './expert-engine.mjs?v=20261102-expert1';
import {makeExpertDemo,SCHEMAS} from './expert-demo.mjs?v=20261102-expert1';
import {plot,connectivityMap,microMap,fmt} from './expert-graphics.mjs?v=20261102-expert1';
import {day,finite} from './expert-stats.mjs?v=20261102-expert1';
import {createPacket,putInbox} from '../shared/decision-inbox.mjs?v=20261102-expert1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={bundle:{source:'尚未载入监测数据',synthetic:false},selected:{},role:'tracer',fastDays:3,image:{},last:null};
const DOMAINS={connectivity:'油层连通监测与研判',stimulation:'压裂酸化效果与研判',eor:'老区提高采收率评价'};
const refs=[['IAEA井间示踪剂技术指南','https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1539_web.pdf'],['Ecopetrol原始方法与现场案例（2020）','https://ctyf.journal.ecopetrol.com.co/index.php/ctyf/article/view/261'],['HFTS-2微地震观测：事件云与裂缝体积差异','https://ocdimage.emnrd.nm.gov/imaging/filestore/SantaFe/CF/20230731/23295_07_31_2023_01_43_23.pdf'],['DOE/NETL CO₂驱控流完井现场研究','https://netl.doe.gov/projects/project-information.aspx?p=FE0031790'],['预测区间与残差Bootstrap方法','https://otexts.com/fpp3/prediction-intervals.html']];
const source=()=>state.bundle.synthetic?'人工构造教学演示 · 非现场实测':state.bundle.source??'用户上传资料（需核验）';
const panel=(title,body,extra='')=>`<section class="panel gap"><div class="panel-head"><h2>${title}</h2>${extra}</div><div class="panel-body">${body}</div></section>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td class="wrap">${x??'未提供'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const conclusions=(petro,stat,history)=>`<div class="expert-conclusions"><p><b>石油工程：</b>${esc(petro)}</p><p><b>概率统计：</b>${esc(stat)}</p><p><b>历史案例：</b>${esc(history)}</p></div>`;
function sourceNotice(){return `<div class="notice ${state.bundle.synthetic?'expert-demo':''}"><b>${esc(source())}</b>。${state.bundle.synthetic?'以下井位、示踪剂、微地震、作业和生产数据均为人工构造，不与Volve井做虚构关联。':'上传数据仅在当前浏览器处理，字段单位、层位与作业时间必须由现场核验。'}可信度描述是证据等级，未校准为“诊断正确概率”。</div>`;}
function controls(){return panel('监测数据接入与字段说明',`<div class="row"><button class="btn" data-expert="demo">载入轻量教学演示</button><button class="btn" data-expert="clear">清空演示，接入实测</button><button class="btn" data-expert="template">↓ 完整JSON格式样例</button><button class="btn" data-expert="csv-template">↓ 当前表CSV样例</button></div><div class="row gap"><label>当前数据表 <select id="expert-role" aria-label="当前数据表">${TABLES.map(k=>`<option ${state.role===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="btn">上传完整监测包JSON / 当前表CSV<input id="expert-upload" type="file" accept=".json,.csv" aria-label="监测数据上传" style="max-width:230px"></label><label class="btn">上传原始监测解释图<input id="expert-image" type="file" accept="image/png,image/jpeg" aria-label="上传监测解释图" style="max-width:230px"></label></div><p class="small-note">单文件≤5MB；每表≤20000行。JSON完整包包含wells、tracer、micro、production、interventions、layers、cases、other数组，也可上传对象行数组替换当前表。CSV需UTF-8、第一行为字段。原始PNG/JPG仅供对照，不自动反演数值。刷新会清空本页监测资料，重要研判请先导出。上传单表覆盖人工场景时继续标为混合演示，完整实测包应先清空再导入。</p>${state.image.connectivity?`<details open><summary>上传的原始监测解释图（仅供人工对照）</summary><img class="expert-source-image" src="${state.image.connectivity}" alt="用户上传监测解释图"></details>`:''}<div class="expert-counts">${TABLES.map(k=>`<span>${k} <b>${state.bundle[k]?.length??0}</b>行</span>`).join('')}</div><details><summary>当前表必需字段、单位与输入示例</summary>${table(['字段','含义与单位'],Object.entries(SCHEMAS[state.role]).map(([k,v])=>[esc(k),esc(v)]))}<pre class="sample">${esc(JSON.stringify((makeExpertDemo()[state.role]??[]).slice(0,1),null,2))}</pre><p>空值留空，不补0。production至少需要well_id、date、oil；tracer至少需要注采井号、time_days、concentration_mg_l和lod_mg_l；micro至少需要同基准x_m、y_m、z_m。</p></details>`);}
function modelCard(name,structure,formula,parameters,caution){return `<article class="expert-model"><h3>${name}</h3><div class="expert-flow">${structure.map((s,i)=>`${i?'<span>→</span>':''}<b>${s}</b>`).join('')}</div><p class="formula">${formula}</p><p>${parameters}</p><p class="small-note">${caution}</p></article>`;}
function theory(domain){const common=modelCard('可追溯专家规则与案例相似检索',['同井/同层/同时间证据','规则触发＋缺口检查','审核案例对照','候选措施待审核'],'E → IF条件 THEN候选措施；d=mean(|x−x案例|/max(1,|x|))','E为示踪剂、生产及空间证据集合；d仅为孔隙度、渗透率、温度共有特征的平均相对距离，不是成功率。只有reviewed=true、synthetic≠true且source可追溯的同类案例才参与检索。','这是规则专家系统，不冒充已经接入大语言模型的自由推理；历史案例仅作外部参考，不能直接迁移效果。');const list=domain==='connectivity'?[modelCard('示踪剂观测积分与一维矩估计',['分井对/分层对/批次','检出限识别与积分','运移矩μ、σ²','连通/快通道候选'],'Mᵣ=10⁻³∫C(t)Q(t)dt；f=Mᵣ/Mᵢ；μ=∫tCQdt/∫CQdt；v=L/μ；D=L²σ²/(2μ³)','C：背景扣除浓度，毫克/升；Q：对应相流量，立方米/日；t：天；Mᵣ、Mᵢ：回收与注入质量，千克；L：米；v：米/日；D：平方米/日。积分采用梯形法。','假定保守脉冲、一维对流弥散；未覆盖拖尾、多通道、吸附或井筒混流会使参数偏差。没有完整误差模型时不生成参数95%区间。若提供浓度、流量、距离和注入质量1σ误差，进行200次独立高斯Monte Carlo（随机种子91），用2.5%/97.5%分位数给出条件参数范围；截断和系统误差会影响覆盖。'),modelCard('微地震空间包络与层位统计',['事件实际xyz','平面凸包/深度分层','几何跨度与定位误差','与流体路径分开校核'],'A=½|Σ(xᵢyᵢ₊₁−xᵢ₊₁yᵢ)|；Δz=zmax−zmin；单轴范围=位置±1.96σ','A：事件平面凸包面积，平方米；Δz：深度跨度，米；σ：上传的单轴1标准差定位误差，米。层位按[top_m,bottom_m)计数。井位与事件必须采用同一坐标基准；平面图蓝点为上传井位，深度图仅对具有depth_m的井位绘点。','几何包络不是导流或支撑体积。单轴高斯定位区间不是三维联合95%区域。')]:[modelCard('措施前趋势反事实基线＋移动块Bootstrap',['措施前30天','OLS前趋势拟合','后30天观测−基线','200次7日块Bootstrap'],'q₀(t)=max(0,a+bt)；ΔN=Σ后期[q观测(t)−q₀(t)]Δt；CI=[Q₂.₅%,Q₉₇.₅%]','q：标准立方米/日；t：距措施日的天数；a、b由前30天至少14个有效日拟合。Δt=1日，仅对有观测日求和。Bootstrap对前/后趋势残差作7日块重采样，重复200次（随机种子47）；数据不外推缺失天。','ΔN是同窗关联差额而非因果增油；没有对照及混杂校正，区间不包括制度变更、模型偏差或计量系统误差。'),modelCard('措施后7日趋势与条件统计区间',['措施后观测','OLS独立拟合','Student-t均值区间','未来观测预测区间'],'ŷ=a+bt；CI均值=ŷ±t₀.₉₇₅s√h；PI单次=ŷ±t₀.₉₇₅s√(1+h)；h=1/n+(t−t̄)²/Σ(tᵢ−t̄)²','s：残差标准差；n：有效观测数；t分布自由度n−2；95%为名义水平。非负截断会改变覆盖；自相关、漂移和短窗需谨慎解释。','这是措施后固定30日评价窗之后的7日外推，不是当前实时预测；薄膜/残余酸、裂缝导流或CO₂相态未被该统计模型显式模拟。')];return panel('实际计算模型 · 结构、公式与参数',`<div class="expert-models">${[...list,common].join('')}</div>`);}
function advicePanel(advice,domain){return panel('专家系统研判与下一步措施',`<div class="notice"><b>${esc(advice.engine)}</b><br>证据可信度：${esc(advice.credibility)}；状态：${esc(advice.status)}。候选措施是筛选建议，药剂、剂量、施工规模和压力窗口需另作专项设计。</div>${table(['证据类别','本批结论'],advice.evidence.map(e=>['观测/计算证据',esc(e)]))}${advice.actions.length?table(['候选措施','推荐依据','实施前需补齐'],advice.actions.map(a=>[esc(a.name),esc(a.reason),esc(a.requirements)])):'<p class="small-note">证据不足，尚未形成具体措施候选。</p>'}<p class="small-note">${esc(advice.gaps.join('；'))}</p><div class="row gap"><button class="btn primary" data-expert="send" data-domain="${domain}">发送到决策平台</button><button class="btn" data-expert="export" data-domain="${domain}">↓ 下载研判交接JSON</button><a class="btn" href="../decision/#monitoring-inbox">打开决策平台收件箱 ↗</a></div><p class="small-note">发送写入同源、同浏览器本地收件箱；不代表服务器、其它用户或现场控制系统已接收。换设备可通过JSON导入。</p>`);}
function connectionView(){const b=state.bundle,traces=tracerAnalysis(b.tracer??[],{fastDays:state.fastDays}),micro=microAnalysis(b.micro??[],b.layers??[]),comparison=compareProduction(b.production??[],traces),advice=expertAdvice({traces,micro,other:b.other??[],synthetic:b.synthetic}),image=state.image.connectivity;state.last={domain:'connectivity',title:DOMAINS.connectivity,source:source(),synthetic:!!b.synthetic,advice,models:['示踪剂积分/一维矩估计','事件凸包/分层计数','专家规则v1'],traces:traces.map(({curve,...t})=>t),productionComparison:comparison,micro:{...micro,events:undefined,polygon:undefined},references:refs,notes:'首见剂时间括区是采样分辨率，不是置信区间；未给测量误差时不生成v/D的95%区间。'};return panel('示踪剂井间/层间连通解释图',`<div class="row"><label>早见剂规则阈值 <input id="expert-fast" type="number" min="0.01" max="365" step="0.5" value="${state.fastDays}"> 天</label><small>工程筛选参数，不是通用行业标准。</small></div>${connectivityMap(b.wells??[],traces)}${image?`<details open><summary>上传的原始解释图（人工对照）</summary><img class="expert-source-image" src="${image}" alt="用户上传示踪剂监测解释图"></details>`:''}${conclusions(traces.length?'井层对按实际检出情况绘图；紫色边为跨层迁移候选，需排除井筒混流；早见剂提示快通道，不能单凭图形确认高渗通道。':'尚无示踪剂表，未生成连通性推断。','首见剂位于“前次未检出—首次检出”的采样括区；回收量为有限观测窗积分。缺乏测量误差时，运移参数置信区间无法计算。','可参考IAEA和Ecopetrol方法；这些是技术/外部案例参考，不是本区块成功率。已审核本地历史案例需另上传。')}`)+panel('见剂时间、见剂量与监测曲线',`${table(['井对 / 层对','首见剂 / 采样括区（天）','峰浓度 / 峰时','回收质量 / 注入质量比例','运移参数','研判及注意事项'],traces.map(t=>[esc(t.injector+'→'+t.producer)+'<br>'+esc((t.layerFrom??'?')+'→'+(t.layerTo??'?')),t.firstArrival===null?'本窗未检出':fmt(t.firstArrival)+' / ['+t.arrivalBracket.map(x=>fmt(x)).join(',')+']',fmt(t.peak,4)+'毫克/升<br>'+fmt(t.peakDay)+'天',fmt(t.recoveredKg,4)+'千克 / '+fmt(t.recoveryFraction===null?null:t.recoveryFraction*100)+'%', 'v='+fmt(t.velocity)+'米/日<br>D='+fmt(t.dispersion)+'平方米/日'+(t.interval?'<br>条件95% v=['+t.interval.velocity95.map(v=>fmt(v)).join(', ')+']，D=['+t.interval.dispersion95.map(v=>fmt(v)).join(', ')+']<br>质量区间['+t.interval.mass95.map(v=>fmt(v,4)).join(', ')+']千克；'+esc(t.interval.method):'<br>95%区间：无法计算（未提供完整实测误差）'),esc(t.conclusion)+'<br>'+esc(t.layerConclusion)+'<br>'+esc(t.caution)]))}<div class="expert-plots">${traces.map((t,i)=>`<article><h3>${esc(t.injector+'→'+t.producer+' '+(t.layerTo??''))}</h3>${plot([{name:'蓝色：实测浓度',color:'#477ca6',points:t.curve.map(r=>({x:r.time_days,y:r.concentration_mg_l}))},{name:'金色：检出限',color:'#b68c50',dash:true,points:t.curve.map(r=>({x:r.time_days,y:Number(r.lod_mg_l)}))}],{unit:'毫克/升',xLabel:'注入后时间（天）',xKind:'number',source:source()})}<p class="small-note">${esc(t.conclusion)} 本图为观测，不是未来预测；检出限不是置信界限。</p></article>`).join('')}</div>`)+panel('微地震及其它手段监测 · 平面与层间剖面',`${micro.available?`<div class="expert-counts"><span>事件 ${micro.events.length}</span><span>无效行 ${micro.invalid}</span><span>事件凸包 ${fmt(micro.areaM2)}平方米</span><span>深度跨度 ${fmt(micro.heightM)}米</span><span>最大单轴95%误差范围 ±${fmt(micro.loc95M)}米</span></div><div class="expert-plots"><article>${microMap(micro,{wells:b.wells??[]})}</article><article>${microMap(micro,{depth:true,wells:b.wells??[]})}</article></div>${table(['层名','层顶/层底（米）','该层事件数'],micro.layers.map(l=>[esc(l.layer),fmt(l.top_m)+' / '+fmt(l.bottom_m),l.count]))}`:'<div class="empty">请上传微地震事件坐标或其它监测解释记录。</div>'}${table(['其它监测','井层','解释及来源'],(b.other??[]).map(r=>[esc(r.method),esc((r.producer??'')+' '+(r.layer_from??'')+'→'+(r.layer_to??'')),esc(r.result)+'<br>'+esc(r.source)]))}${conclusions(micro.conclusion,'微地震与示踪剂目前独立展示，未自动证明同井同层同时间窗一致。若提供单轴定位标准差σ，显示±1.96σ条件误差范围；未提供则无法计算。事件数量不直接转成连通概率。', '外部HFTS-2观测说明事件云与有效裂缝体积可能不同；本批未提供支撑剂运移、导流或同期干扰试井时不确认有效支撑。')}`)+panel('与实际生产对照',`${table(['生产井','注入日期/样本数','日产油差（标准立方米/日）','含水差（百分点）','压力差（兆帕）','判断'],comparison.map(r=>[esc(r.producer),esc(r.window)+' / '+r.nBefore+'→'+r.nAfter,fmt(r.oilChange),fmt(r.waterCutChange),fmt(r.pressureChange),esc(r.conclusion)]))}${conclusions('对照注入前14天与注入后第14—27天，避免把不同井层、不同日期混合比较。','表中是同窗均值变化，尚未作因果对照或显著性检验，不输出“通道概率”。','现场案例需匹配同层系、同注采制度和井筒条件。')}`)+advicePanel(advice,'connectivity');}
function effectView(domain){const b=state.bundle,jobs=(b.interventions??[]).filter(j=>domain==='stimulation'?['压裂','酸化'].includes(j.type):!['压裂','酸化'].includes(j.type));const job=jobs.find(j=>j.id===state.selected[domain])??jobs[0];if(!job)return panel('选择措施与作业记录','<p>尚无该类措施。请载入轻量演示或上传interventions与production表；前后至少各14个有效日。</p>');state.selected[domain]=job.id;const r=measureAnalysis(b.production??[],job,b.layers??[],b.cases??[]);const selector=`<label>评价措施 <select id="expert-job" aria-label="评价措施" data-domain="${domain}">${jobs.map(j=>`<option value="${esc(j.id)}" ${j.id===job.id?'selected':''}>${esc(j.well_id+' · '+j.type+' · '+j.date)}</option>`).join('')}</select></label>`;if(!r.available)return panel('措施选择与数据覆盖',selector+'<div class="notice error">'+esc(r.reason)+'</div>');const micro=microAnalysis((b.micro??[]).filter(e=>e.job_id===job.id||(!e.job_id&&e.well_id===job.well_id)),b.layers??[]),advice=expertAdvice({effect:r,micro,synthetic:b.synthetic}),records=r.points,sourceTag=source();state.last={domain,title:DOMAINS[domain],source:sourceTag,synthetic:!!b.synthetic,advice,models:['措施前趋势反事实基线','7日移动块Bootstrap200次','措施后OLS＋Student-t条件95%区间','审核案例相似检索'],job,incrementOil:r.incrementOil,effectCI:r.effectCI,coverageDays:r.coverageDays,forecast:r.future,confidence:r.confidence,causalNote:r.causalNote,matchedCases:r.matchedCases,references:refs};const point=(k)=>records.map(v=>({x:day(v.date),y:finite(v[k])?Number(v[k]):null}));const caseText=r.matchedCases.length?`匹配到${r.matchedCases.length}条已审核同类案例，仅作经验对照；相似度不是本井成功率。`:'未提供已审核且可追溯的同类历史案例，不虚构案例支持或成功概率。';return panel('措施选择、作业参数与评价范围',`${selector}<div class="notice">${esc(job.type)} · ${esc(job.well_id)} · 实施日期${esc(job.date)}；评价窗为实施前30天和后30天。前${r.pre.length} / 后${r.post.length}个有效产油日。${r.fullWindow?'后期观测窗完整。':'后期缺测，不外推缺测天累计增油。'}</div><div class="expert-counts"><span>平均日产油 ${fmt(r.before)}→${fmt(r.after)}</span><span>产油差额 ${fmt(r.incrementOil)}标准立方米</span><span>关联95%CI [${r.effectCI.map(x=>fmt(x)).join(', ')}]</span><span>压力变化 ${fmt(r.deltaPressure)}兆帕</span><span>计算 ${fmt(r.duration,4)}秒</span></div>${table(['作业参数','上传值与单位','解释/限制'],[['施工液量 / 酸量',fmt(job.fluid_m3)+' / '+fmt(job.acid_m3)+'立方米','规模为作业记录；不自动推定有效波及范围'],['破裂压力 / 最高施工压力',fmt(job.breakdown_mpa)+' / '+fmt(job.peak_treating_mpa)+'兆帕','需同一压力测点及静液柱/摩阻修正口径'],['独立解释裂缝半长 / 缝高',fmt(job.frac_half_length_m)+' / '+fmt(job.frac_height_m)+'米','无独立解释不由微地震点云直接替代'],['支撑剂 / 独立导流能力',fmt(job.proppant_t)+'吨 / '+fmt(job.conductivity_md_m)+'毫达西·米','加砂量不等于有效支撑；需闭合压力、支撑分布及导流实验'],['酸化波及半径',fmt(job.acid_radius_m)+'米','仅使用上传专项解释值；未提供则不估算'],['返排起止 / 见油作业记录',esc(job.flowback_start_date??'未提供')+'—'+esc(job.flowback_end_date??'未提供')+' / '+esc(job.first_oil_date??'未提供'),'排液历时：'+(Number.isFinite(day(job.flowback_start_date))&&Number.isFinite(day(job.flowback_end_date))?fmt(day(job.flowback_end_date)-day(job.flowback_start_date))+'天':'未提供')+'；见油滞后：'+(Number.isFinite(day(job.first_oil_date))?fmt(day(job.first_oil_date)-day(job.date))+'天':'未提供')+'。作业记录优先，首个正产油记录不能当真实见油时间。'],['观测窗累计返排液',fmt(job.flowback_m3)+'立方米','须与注入液同窗比较；返排含地层水时不能直接称液体回收率'],['CO₂累计注入 / 聚合物浓度',fmt(job.co2_injected_t)+'吨 / '+fmt(job.polymer_conc_mg_l)+'毫克/升','CO₂相态、最小混相压力与腐蚀/完整性；聚合物配伍、黏度、吸附及注入能力需专项评价']])}`)+panel('措施前后油气水与压力曲线',`<div class="expert-plots"><article><h3>日产油及无措施前趋势基线</h3>${plot([{name:'蓝色：实测日产油',color:'#477ca6',points:point('oil')},{name:'金色：前趋势基线＋95%均值CI',color:'#b68c50',dash:true,bandName:'条件95%基线均值置信区间',points:records.map(v=>({x:day(v.date),y:v.baseline.prediction,low:v.baseline.meanLow95,high:v.baseline.meanHigh95}))}],{unit:'标准立方米/日',marker:day(job.date),source:sourceTag})}</article>${[['water','日产水','#397e68','标准立方米/日'],['gas','日产气','#8753a0','标准立方米/日'],['pressure','压力','#b02a35','兆帕']].map(([k,n,c,u])=>`<article><h3>${n} · 措施前后观测</h3>${plot([{name:n+'观测',color:c,points:point(k)}],{unit:u,marker:day(job.date),source:sourceTag})}</article>`).join('')}</div>${conclusions(r.incrementOil>0?'后期产油高于前趋势基线；需排除开井率、配产、计量与同期注采调整。':'后期产油未显示高于前趋势基线，需核查返排、伤害、供液及措施适配。',`${r.intervalMethod}。14—30日短窗仅约2—4个7日块，区间可能不稳定；${r.causalNote}候选拐点：${r.turning?.date??'资料不足'}，按最大7日滚动均值差探索，未经多重检验。`,caseText)}`)+panel('措施后7日预测 · 可信度与区间',`${plot([{name:'蓝色：措施后有效日观测',color:'#477ca6',points:r.post.map(v=>({x:day(v.date),y:Number(v.oil)}))},{name:'红色虚线：后趋势预测＋95%PI',color:'#b02a35',dash:true,bandName:'条件95%单次观测预测区间（PI）',points:r.future.map(v=>({x:day(v.date),y:v.prediction,low:v.low95,high:v.high95}))}],{unit:'日产油，标准立方米/日',source:sourceTag})}${table(['预测日期','点预测','95%均值置信区间CI','95%单次预测区间PI','来源模型/可信度'],r.future.map(v=>[v.date,fmt(v.prediction),'['+fmt(v.meanLow95)+', '+fmt(v.meanHigh95)+']','['+fmt(v.low95)+', '+fmt(v.high95)+']',esc(v.model)+'<br>'+esc(v.confidence)]))}<p>${esc(r.future[0].assumptions)}。${esc(r.confidence)}。覆盖率未经本油田独立回测验证；95%不是“预测正确率95%”。</p><button class="btn" data-expert="forecast">↓ 下载本措施预测及区间CSV</button>`)+(domain==='stimulation'?panel('造缝波及、层间活动与支撑证据',`${micro.available?`<div class="expert-plots"><article>${microMap(micro,{wells:b.wells??[]})}</article><article>${microMap(micro,{depth:true,wells:b.wells??[]})}</article></div><p>事件云几何跨度：X ${fmt(micro.widthM)}米、Y ${fmt(micro.lengthM)}米、深度${fmt(micro.heightM)}米。单轴95%定位范围±${fmt(micro.loc95M)}米。</p>`:'<p>当前措施没有匹配微地震事件；不会复用其它井/其它措施的事件云。</p>'}${conclusions('微地震可描述破裂活动，专项解释半长/缝高/酸化半径与导流能力来自作业或实验资料，缺失则显示未提供。','几何范围无自动“支撑概率”；定位误差需要实测σ。裂缝导流寿命与未来增产不由点云包络直接确定。',caseText)}`):panel('老区静态参数、注入过程与剩余油约束',`${table(['静态参数','上传值','判断边界'],[['目标层',esc(job.layer??'未提供'),'地层压力/孔隙度/渗透率须来自同层资料'],['孔隙度 / 渗透率',fmt(r.layer?.porosity,3)+' / '+fmt(r.layer?.perm_md)+'毫达西','孔隙度采用0—1小数'],['原始压力 / 当前均压',fmt(r.layer?.initial_pressure_mpa)+' / '+fmt(r.pressureAfter)+'兆帕','压力基准和测点须一致，井底流压不能直接冒称地层压力'],['相对原始压力降（条件值）',r.layer?.pressure_basis&&r.post.filter(v=>finite(v.pressure)).every(v=>v.pressure_basis===r.layer.pressure_basis)&&finite(r.layer.initial_pressure_mpa)&&r.pressureAfter!==null?fmt(Number(r.layer.initial_pressure_mpa)-r.pressureAfter)+'兆帕':'未计算：尚未确认同一压力基准','Δp=原始压力−当前压力；禁止把地层静压与井底流压直接相减'],['剩余油饱和度',fmt(r.layer?.remaining_oil_sat,3),'需要测井/取心/试验解释，不由生产趋势直接反演'],['原始地质储量',fmt(r.layer?.ooip_m3)+'标准立方米','短期生产差额不等于最终采收率提升，当前不输出虚构采收率收益']])}${['injection_co2_t','polymer_kg_d'].map((k,i)=>{const rs=records.filter(r=>finite(r[k]));return rs.length?`<h3>${i?'聚合物':'CO₂'}注入记录</h3>${plot([{name:i?'聚合物质量':'CO₂质量',color:i?'#8753a0':'#397e68',points:rs.map(r=>({x:day(r.date),y:Number(r[k])}))}],{unit:i?'千克/日':'吨/日',marker:day(job.date),source:sourceTag})}`:'';}).join('')}${conclusions('结合产油、压力、含水及注入过程观察阶段性响应。CO₂气窜、聚合物吸附/剪切与调剖后的分层吸水变化需独立监测。','表观拐点与前后差额仅支持关联评价；要计算措施因果效益或最终采收率，需同期对照、长期累产、OOIP与模拟/物质平衡约束。',caseText)}`))+panel('历史案例对照',`${r.matchedCases.length?table(['案例ID','同类工艺/相对距离','原案例效果','原始出处'],r.matchedCases.map(c=>[esc(c.id),esc(c.type)+' / '+fmt(c.similarityDistance,3),esc(c.outcome),`<a target="_blank" rel="noopener" href="${esc(c.source)}">原案例来源 ↗</a>`])):'<p>当前未命中已审核同类案例。可上传cases表的reviewed布尔标记、原始source链接与真实效果；人工演示不参与历史成功率统计。</p>'}`)+advicePanel(advice,domain);}
export function expertPage(domain){let body;try{body=domain==='connectivity'?connectionView():effectView(domain);}catch(e){state.last=null;body=panel('数据需要修正','<div class="notice error">'+esc(e.message)+'</div>');}return `<div class="expert-workspace">${sourceNotice()}${controls()}${body}${theory(domain)}${panel('技术参考与区间使用注意',`<p>预测区间（PI）描述未来观测的不确定范围，均值置信区间（CI）描述模型均值的不确定范围，采样括区与定位误差范围又是不同概念。缺乏独立校准或误差模型时，可信度及置信区间明确为无法计算，不填造百分比。</p>${refs.map(([n,u])=>`<p><a href="${u}" target="_blank" rel="noopener">${n} ↗</a></p>`).join('')}`)}</div>`;}
export function bindExpert({render,toast,parseCSV,csv,save}){document.querySelectorAll('[data-expert]').forEach(el=>el.onclick=()=>{try{const action=el.dataset.expert;if(action==='demo'){state.bundle=validateBundle(makeExpertDemo());state.last=null;toast('已载入人工教学场景，非现场实测');render();}else if(action==='clear'){state.bundle={synthetic:false,source:'尚未载入实测监测数据'};state.selected={};state.last=null;for(const u of Object.values(state.image))URL.revokeObjectURL(u);state.image={};render();}else if(action==='template')save('监测与措施_人工格式样例.json',JSON.stringify(makeExpertDemo(),null,2),'application/json');else if(action==='csv-template'){const rows=makeExpertDemo()[state.role]??[];save(state.role+'_人工格式样例.csv',rows.length?csv(rows):'\ufeff'+Object.keys(SCHEMAS[state.role]).join(',')+'\n');}else if(action==='send'||action==='export'){if(!state.last||state.last.domain!==el.dataset.domain||!state.last.advice.evidence.length)throw Error('请先载入合规资料并生成当前页面研判');const packet=createPacket(state.last.domain,state.last);if(action==='send'){putInbox(packet);toast('已写入同浏览器决策平台本地收件箱，尚未专家审核');}else save('监测研判交接_'+packet.domain+'.json',JSON.stringify(packet,null,2),'application/json');}else if(action==='forecast'){if(!state.last?.forecast)throw Error('暂无预测');save('措施后预测与置信区间.csv',csv(state.last.forecast.map(r=>({...r,source:source(),unit:'标准立方米/日',synthetic:!!state.bundle.synthetic}))));}}catch(e){toast(e.message);}});document.querySelector('#expert-role')?.addEventListener('change',e=>{state.role=e.target.value;render();});document.querySelector('#expert-fast')?.addEventListener('change',e=>{const x=Number(e.target.value);if(!Number.isFinite(x)||x<=0||x>365){toast('早见剂阈值须为0—365天内的正数');return;}state.fastDays=x;render();});document.querySelector('#expert-job')?.addEventListener('change',e=>{state.selected[e.target.dataset.domain]=e.target.value;render();});document.querySelector('#expert-upload')?.addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)throw Error('监测文件上限5MB，请先提取轻量特征');const input=/\.json$/i.test(f.name)?JSON.parse(await f.text()):parseCSV(await f.text());let bundle;if(Array.isArray(input)){const rows=input.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,['reviewed','synthetic'].includes(k)?v===true||v==='true':v])));bundle={...state.bundle,[state.role]:rows,source:state.bundle.synthetic?'混合：人工演示＋用户单表':'用户上传：'+f.name};}else bundle={...input,source:'用户上传：'+f.name,synthetic:input.synthetic===true};state.bundle=validateBundle(bundle);state.selected={};state.last=null;render();toast('监测数据已载入；未自动关联Volve井');}catch(e){toast(e.message);}});document.querySelector('#expert-image')?.addEventListener('change',e=>{try{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg'].includes(f.type)||f.size>5*1024*1024)throw Error('解释图仅支持5MB内PNG/JPG');if(state.image.connectivity)URL.revokeObjectURL(state.image.connectivity);state.image.connectivity=URL.createObjectURL(f);render();}catch(e){toast(e.message);}});}
